import { advanceGame } from '../advance-game.ts';
import { isWon } from '../is-won.ts';
import type { SessionState } from './session-state.ts';

export const CLOCK_RENDER_MS = 100;

export function advanceSession(session: SessionState, now: number): SessionState {
  const atMs = Math.max(session.atMs, now);
  const game = session.visible && !session.paused
    ? advanceGame(session.game, atMs - session.atMs)
    : session.game;
  return { ...session, game, atMs };
}

export function setSessionVisibility(session: SessionState, now: number, visible: boolean): SessionState {
  return { ...advanceSession(session, now), visible };
}

export function resumeSession(session: SessionState, now: number): SessionState {
  return { ...advanceSession(session, now), paused: false, loadStatus: '' };
}

export function isClockRunning(session: SessionState): boolean {
  return session.visible && !session.paused && session.game.started && !isWon(session.game);
}

export function nextClockDelay(session: SessionState): number {
  return session.game.selection.kind === 'mismatch'
    ? Math.max(1, Math.min(CLOCK_RENDER_MS, Math.ceil(session.game.selection.remainingMs)))
    : CLOCK_RENDER_MS;
}

export const SHAPES = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
export const MARKERS = ['top', 'top-right', 'right', 'bottom-right', 'bottom', 'bottom-left', 'left', 'top-left'] as const;
export const FILLS = ['solid', 'outline'] as const;
export const PALETTE = [
  { name: 'cyan', color: '#63E7FF' }, { name: 'magenta', color: '#FF71D6' },
  { name: 'green', color: '#8BEA7D' }, { name: 'yellow', color: '#FFE082' },
  { name: 'orange', color: '#FFB064' }, { name: 'violet', color: '#B49AFF' },
  { name: 'rose', color: '#FF8296' }, { name: 'ice', color: '#D9F3FF' },
] as const;
const DIAGONAL = 40 / Math.sqrt(2);
const OFFSETS = [
  [0, -40], [DIAGONAL, -DIAGONAL], [40, 0], [DIAGONAL, DIAGONAL],
  [0, 40], [-DIAGONAL, DIAGONAL], [-40, 0], [-DIAGONAL, -DIAGONAL],
] as const;

export function faceIdentity(id: number) {
  if (!Number.isInteger(id) || id < 0 || id > 127) throw new Error('Invalid face identity');
  const markerIndex = Math.floor(id / 8) % 8;
  const shape = SHAPES[id % 8];
  const marker = MARKERS[markerIndex];
  const fill = FILLS[Math.floor(id / 64)];
  const palette = PALETTE[markerIndex];
  const offset = OFFSETS[markerIndex];
  if (shape === undefined || marker === undefined || fill === undefined || palette === undefined || offset === undefined) {
    throw new Error('Incomplete face identity');
  }
  return {
    shape, marker, fill, color: palette.color, x: 50 + offset[0], y: 50 + offset[1],
    name: `${palette.name} ${fill} ${shape}, marker ${marker}`,
  };
}
import { faceIdentity } from './face-identity.ts';

export interface FaceProps { readonly id: number }

const PATHS = {
  triangle: 'M50 25 75 75 25 75Z',
  diamond: 'M50 25 75 50 50 75 25 50Z',
  star: 'M50 25 57.3 39.9 73.8 42.3 61.9 53.9 64.7 70.2 50 62.5 35.3 70.2 38.1 53.9 26.2 42.3 42.7 39.9Z',
  hexagon: 'M50 25 71.65 37.5 71.65 62.5 50 75 28.35 62.5 28.35 37.5Z',
  plus: 'M42 25H58V42H75V58H58V75H42V58H25V42H42Z',
  chevron: 'M25 25 50 45 75 25V50L50 75 25 50Z',
} as const;

export function Face({ id }: FaceProps) {
  const face = faceIdentity(id);
  const shape = face.shape === 'circle' ? <circle cx="50" cy="50" r="25" />
    : face.shape === 'square' ? <rect x="25" y="25" width="50" height="50" />
      : <path d={PATHS[face.shape]} />;
  return (
    <svg className="card-face" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <g fill={face.fill === 'solid' ? face.color : 'none'}
        stroke={face.fill === 'outline' ? face.color : 'none'} strokeWidth="5" strokeLinejoin="round">
        {shape}
      </g>
      <circle cx={face.x} cy={face.y} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
    </svg>
  );
}
export const MOVEMENT_KEYS = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'] as const;
export type MovementKey = (typeof MOVEMENT_KEYS)[number];

export function isMovementKey(key: string): key is MovementKey {
  return MOVEMENT_KEYS.some(value => value === key);
}

export function focusDestination(index: number, size: number, key: MovementKey): number {
  const column = index % size;
  const row = Math.floor(index / size);
  switch (key) {
    case 'ArrowLeft': return column > 0 ? index - 1 : index;
    case 'ArrowRight': return column < size - 1 ? index + 1 : index;
    case 'ArrowUp': return row > 0 ? index - size : index;
    case 'ArrowDown': return row < size - 1 ? index + size : index;
  }
}
